/**
 * Model Comparison Matrix — tool-local actions.
 *
 * Category: AI / LLM Product Management (squad S12b)
 * Tool:     Per-model cost / latency / context-window / eval-score matrix
 *           with a lifecycle status.
 *
 * Agent surface: tool.model_comparison.*
 * Backing CRUD : workspace.model.* (auto-generated by defineCrudActions in
 *                src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (see hallucination-log.ts for the analog) ──
 * Model entries are a record-keeping entity — generic create / list /
 * update / delete already exist via workspace.model.*. This file adds the
 * domain verbs:
 *
 *   1. list_state  — counts byStatus / byVendor, plus best-in-class picks
 *                    (cheapest input, fastest p50, highest eval) computed
 *                    only over entries that actually carry that metric.
 *   2. add_model   — register a model (status defaults to "evaluation").
 *   3. set_status  — promote / deprecate a model by id → {updated}.
 *
 * Entity kind "workspace:model" (kindFromToolId of "workspace.model")
 * matches the browser sync engine, so MCP writes round-trip into the UI.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverUpsertEntity, serverVersionedUpdate } from "../server-store";
import type { ModelEntry } from "@/lib/stores/workspace-types";

const KIND_MODEL = "workspace:model";

/** Closed enum of lifecycle statuses. Matches ModelEntry.status verbatim. */
const STATUSES = ["production", "evaluation", "experimental", "deprecated"] as const;
const StatusSchema = z.enum(STATUSES);

const ws = () => useWorkspaceStore.getState();

/** Name of the entry minimising (or maximising) a metric, considering ONLY
 *  entries where the metric is defined. Returns null when none carry it —
 *  so the agent never sees a misleading "cheapest: <model with no price>". */
function pick(
  items: ModelEntry[],
  metric: keyof ModelEntry,
  dir: "min" | "max"
): { name: string; value: number } | null {
  let best: { name: string; value: number } | null = null;
  for (const m of items) {
    const v = m[metric];
    if (typeof v !== "number" || Number.isNaN(v)) continue;
    if (best === null || (dir === "min" ? v < best.value : v > best.value)) {
      best = { name: m.name, value: v };
    }
  }
  return best;
}

function countBy(items: ModelEntry[], key: "status" | "vendor"): Record<string, number> {
  const acc: Record<string, number> = {};
  for (const m of items) {
    const k = m[key];
    if (k) acc[k] = (acc[k] ?? 0) + 1;
  }
  return acc;
}

function summarize(items: ModelEntry[]) {
  return {
    total: items.length,
    byStatus: countBy(items, "status"),
    byVendor: countBy(items, "vendor"),
    cheapestInput: pick(items, "inputCostPer1k", "min"),
    fastestP50: pick(items, "latencyP50Ms", "min"),
    highestEval: pick(items, "evalScore", "max"),
    largestContext: pick(items, "contextWindow", "max"),
    items,
  };
}

// ──────── tool.model_comparison.list_state ────────
registry.register({
  id: "tool.model_comparison.list_state",
  toolId: "tool.model_comparison",
  name: "list_state",
  category: "read",
  description:
    "List all models with comparison summary. Returns {total, byStatus, byVendor, cheapestInput, fastestP50, highestEval, largestContext, items}. Each pick is {name, value} computed only over models carrying that metric, or null when none do.",
  paramsSchema: z.object({}),
  handler: async () => summarize(ws().models ?? []),
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<ModelEntry>(ctx.userId, KIND_MODEL);
    return summarize(items);
  },
});

// ──────── tool.model_comparison.add_model ────────
registry.register({
  id: "tool.model_comparison.add_model",
  toolId: "tool.model_comparison",
  name: "add_model",
  category: "write",
  requiresConfirmation: false,
  description:
    "Register a model in the comparison matrix. status defaults to 'evaluation'. Cost fields are USD per 1k tokens; latency fields are milliseconds; evalScore is a 0..1 quality metric. Returns {added: true, id}.",
  paramsSchema: z.object({
    name: z.string().min(1).max(200),
    vendor: z.string().min(1).max(200),
    status: StatusSchema.default("evaluation"),
    inputCostPer1k: z.number().min(0).optional(),
    outputCostPer1k: z.number().min(0).optional(),
    contextWindow: z.number().int().positive().optional(),
    latencyP50Ms: z.number().min(0).optional(),
    latencyP95Ms: z.number().min(0).optional(),
    evalScore: z.number().optional(),
    notes: z.string().max(2000).optional(),
  }),
  handler: async (params) => {
    const entry: ModelEntry = { id: crypto.randomUUID(), ...params };
    ws().upsertModel(entry);
    return { added: true, id: entry.id };
  },
  mcpHandler: async (params, ctx) => {
    // Stamp version 1 on create so the optimistic-concurrency token starts
    // monotonic (audit MEDIUM). The browser path gets this for free —
    // upsertModel stamps version on a first insert.
    const entry: ModelEntry = { id: crypto.randomUUID(), ...params, version: 1 };
    await serverUpsertEntity<ModelEntry>(ctx.userId, KIND_MODEL, entry);
    return { added: true, id: entry.id };
  },
});

// ──────── tool.model_comparison.set_status ────────
// Convenience over workspace.model.update for the most common edit: moving
// a model through its lifecycle (evaluation → production → deprecated).
// Additive in spirit (only the status field changes) → no confirmation.
registry.register({
  id: "tool.model_comparison.set_status",
  toolId: "tool.model_comparison",
  name: "set_status",
  category: "write",
  requiresConfirmation: false,
  description:
    "Set a model's lifecycle status (production | evaluation | experimental | deprecated). Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    status: StatusSchema,
  }),
  handler: async (params) => {
    const current = (ws().models ?? []).find((m) => m.id === params.id);
    if (!current) return { updated: false };
    ws().upsertModel({ ...current, status: params.status });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    // CAS read-modify-write (audit MEDIUM). serverVersionedUpdate returns
    // null for an unknown id, so the not-found path needs no pre-read.
    const res = await serverVersionedUpdate<ModelEntry>(
      ctx.userId,
      KIND_MODEL,
      params.id,
      (cur) => ({ ...cur, status: params.status })
    );
    return { updated: res !== null };
  },
});
